t.script:
//
document.addEventListener('DOMContentLoaded', function () {
    var selectBcg     = document.getElementById('select_bcg');
    var infoBcg       = document.getElementById('info_bcg');
    var sectionLignes = document.getElementById('section_lignes');
    var sectionObs    = document.getElementById('section_observations');
    var btnSoumettre  = document.getElementById('btn_soumettre');
    var btnAjouter    = document.getElementById('btn_ajouter_ligne');
    var tbody         = document.getElementById('tbody_lignes');
    var lblDate       = document.getElementById('lbl_date_expiration');
    var csrfToken     = document.querySelector('[name=csrf_token]') ?
                        document.querySelector('[name=csrf_token]').value : '';
    var lignesBcg     = [];
    var lineIndex     = 1;

    function buildProductOptions() {
        var opts = '<option value="">-- Choisir --</option>';
        lignesBcg.forEach(function (l) {
            opts += '<option value="' + l.product_tmpl_id + '" ' +
                'data-max="' + l.quantity_restante + '" ' +
                'data-conds=\'' + JSON.stringify(l.conditionnements) + '\'>' +
                l.product_name + ' (max ' + parseFloat(l.quantity_restante).toFixed(2) + ' T)' +
                '</option>';
        });
        return opts;
    }

    function buildCondOptions(condList) {
        var opts = '<option value="">-- Choisir --</option>';
        condList.forEach(function (c) {
            opts += '<option value="' + c.id + '">' + c.name + '</option>';
        });
        return opts;
    }

    function ajouterLigne() {
        var idx = lineIndex++;
        var productOpts = buildProductOptions();
        var row =
            '<tr class="ligne-planif" data-index="' + idx + '">' +
            '<td><select name="product_' + idx + '" class="form-select form-select-sm select-product" required style="pointer-events:auto;" data-index="' + idx + '">' + productOpts + '</select></td>' +
            '<td><select name="cond_' + idx + '" class="form-select form-select-sm select-cond" required style="pointer-events:auto;" data-index="' + idx + '"><option value="">-- Choisir produit --</option></select></td>' +
            '<td><input type="date" name="date_' + idx + '" class="form-control form-control-sm" style="pointer-events:auto;" required/></td>' +
            '<td><input type="number" name="qty_' + idx + '" step="0.01" min="0.01" class="form-control form-control-sm input-qty" style="pointer-events:auto;" data-index="' + idx + '" required/></td>' +
            '<td><input type="number" name="rotation_' + idx + '" min="1" value="1" class="form-control form-control-sm" style="pointer-events:auto;" required/></td>' +
            '<td><button type="button" class="btn btn-sm btn-danger btn-suppr" style="pointer-events:auto;"><i class="fa fa-trash"></i></button></td>' +
            '</tr>';
        tbody.insertAdjacentHTML('beforeend', row);
        attachListeners(tbody.lastElementChild);
    }

    function attachListeners(row) {
        var selProduct = row.querySelector('.select-product');
        var selCond    = row.querySelector('.select-cond');
        var inputQty   = row.querySelector('.input-qty');
        var btnSuppr   = row.querySelector('.btn-suppr');

        if (selProduct) {
            selProduct.addEventListener('change', function () {
                var opt = this.options[this.selectedIndex];
                var condList = [];
                try { condList = JSON.parse(opt.getAttribute('data-conds') || '[]'); } catch(e) {}
                var maxQty = parseFloat(opt.getAttribute('data-max') || 0);
                if (selCond) selCond.innerHTML = buildCondOptions(condList);
                if (condList.length === 1 && selCond) selCond.value = condList[0].id;
                if (inputQty) { inputQty.max = maxQty; inputQty.value = ''; }
            });
        }

        if (btnSuppr) {
            btnSuppr.addEventListener('click', function () {
                if (tbody.querySelectorAll('.ligne-planif').length > 1) row.remove();
            });
        }
    }

    tbody.querySelectorAll('.ligne-planif').forEach(attachListeners);

    if (btnAjouter) {
        btnAjouter.addEventListener('click', function () {
            if (lignesBcg.length === 0) return;
            ajouterLigne();
        });
    }

    if (selectBcg) {
        selectBcg.addEventListener('change', function () {
            var bcgId = this.value;
            if (!bcgId) {
                if (infoBcg) infoBcg.style.display       = 'none';
                if (sectionLignes) sectionLignes.style.display = 'none';
                if (sectionObs) sectionObs.style.display    = 'none';
                if (btnSoumettre) btnSoumettre.disabled       = true;
                if (tbody) tbody.innerHTML                    = '';
                lignesBcg = [];
                return;
            }

            fetch('/my/gica/planifications/lignes_bcg', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'X-CSRFToken': csrfToken },
                body: JSON.stringify({ jsonrpc: '2.0', method: 'call', id: 1, params: { bcg_id: parseInt(bcgId) } }),
            })
            .then(function (r) { return r.json(); })
            .then(function (data) {
                var result = data.result || {};
                lignesBcg = result.lignes || [];

                if (lblDate) lblDate.textContent = result.date_expiration || '';
                if (infoBcg) infoBcg.style.display = '';
                lineIndex = 1;
                if (tbody) tbody.innerHTML = '';

                if (lignesBcg.length > 0) {
                    ajouterLigne();
                    lineIndex = 1;
                    if (sectionLignes) sectionLignes.style.display = '';
                    if (sectionObs) sectionObs.style.display    = '';
                    if (btnSoumettre) btnSoumettre.disabled       = false;
                } else {
                    if (tbody) tbody.innerHTML = '<tr><td colspan="6" class="text-center text-muted">Aucun produit disponible dans ce BCG.</td></tr>';
                    if (btnSoumettre) btnSoumettre.disabled = true;
                }
            })
            .catch(function (err) { console.error(err); });
        });

        /* CORRECTION PRINCIPALE :
           Si les lignes sont deja rendues par le serveur (bcg_selectionne),
           ne pas declencher le AJAX qui efface tout.
           Charger seulement lignesBcg en arriere-plan pour permettre ajout de lignes. */
        var lignesExistantes = tbody.querySelectorAll('.ligne-planif');
        if (selectBcg.value && lignesExistantes.length === 0) {
            selectBcg.dispatchEvent(new Event('change'));
        } else if (selectBcg.value && lignesExistantes.length > 0) {
            lineIndex = lignesExistantes.length;
            fetch('/my/gica/planifications/lignes_bcg', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'X-CSRFToken': csrfToken },
                body: JSON.stringify({ jsonrpc: '2.0', method: 'call', id: 1, params: { bcg_id: parseInt(selectBcg.value) } }),
            })
            .then(function (r) { return r.json(); })
            .then(function (data) {
                var result = data.result || {};
                lignesBcg = result.lignes || [];
            })
            .catch(function (err) { console.error(err); });
        }
    }
});

    // ── Flatpickr : grisage visuel dates verrouillees ──────────────────
    (function() {
        // Charger Flatpickr CSS
        var link = document.createElement('link');
        link.rel = 'stylesheet';
        link.href = 'https://cdnjs.cloudflare.com/ajax/libs/flatpickr/4.6.13/flatpickr.min.css';
        document.head.appendChild(link);

        // CSS personnalise pour les jours bloques (meme style que cote commercial)
        var style = document.createElement('style');
        style.textContent = [
            '.flatpickr-day.gica-verrouille,',
            '.flatpickr-day.gica-verrouille:hover {',
            '    background: repeating-linear-gradient(',
            '        45deg, #f8d7da, #f8d7da 4px, #fff5f5 4px, #fff5f5 9px',
            '    ) !important;',
            '    color: #c0392b !important;',
            '    cursor: not-allowed !important;',
            '    pointer-events: none !important;',
            '}',
            '.flatpickr-day.flatpickr-disabled {',
            '    background: repeating-linear-gradient(',
            '        45deg, #f8d7da, #f8d7da 4px, #fff5f5 4px, #fff5f5 9px',
            '    ) !important;',
            '    color: #c0392b !important;',
            '    cursor: not-allowed !important;',
            '    opacity: 1 !important;',
            '}'
        ].join('\n');
        document.head.appendChild(style);

        var periodes = [];
        var flatpickrInstances = [];

        // Charger Flatpickr JS puis les periodes
        var script = document.createElement('script');
        script.src = 'https://cdnjs.cloudflare.com/ajax/libs/flatpickr/4.6.13/flatpickr.min.js';
        script.onload = function() {
            fetch('/gica/periodes_verrouillees', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ jsonrpc: '2.0', method: 'call', id: 1, params: {} }),
            })
            .then(function(r) { return r.json(); })
            .then(function(data) {
                periodes = data.result || [];
                appliquerFlatpickr();
            })
            .catch(function(e) {
                console.warn('Erreur periodes:', e);
                appliquerFlatpickr();
            });
        };
        document.head.appendChild(script);

        function estDateInterdite(dateStr) {
            // dateStr format YYYY-MM-DD
            var d = new Date(dateStr + 'T00:00:00');
            var jour = d.getDay(); // 0=dim,1=lun,...,5=ven,6=sam
            if (jour === 5 || jour === 6) return true;
            for (var i = 0; i < periodes.length; i++) {
                if (dateStr >= periodes[i].from && dateStr <= periodes[i].to) return true;
            }
            return false;
        }

        function getTooltip(dateStr) {
            var d = new Date(dateStr + 'T00:00:00');
            var jour = d.getDay();
            if (jour === 5) return 'Vendredi non ouvrable';
            if (jour === 6) return 'Samedi non ouvrable';
            for (var i = 0; i < periodes.length; i++) {
                if (dateStr >= periodes[i].from && dateStr <= periodes[i].to) {
                    return 'Periode verrouillee : ' + periodes[i].name;
                }
            }
            return '';
        }

        function toYMD(date) {
            var y = date.getFullYear();
            var m = String(date.getMonth() + 1).padStart(2, '0');
            var d = String(date.getDate()).padStart(2, '0');
            return y + '-' + m + '-' + d;
        }

        function initFlatpickr(input) {
            if (input._flatpickr) return; // deja initialise
            // Cacher l'input natif, creer un input texte visible
            input.type = 'hidden';
            var wrapper = document.createElement('div');
            wrapper.style.position = 'relative';
            input.parentNode.insertBefore(wrapper, input);
            wrapper.appendChild(input);

            var display = document.createElement('input');
            display.type = 'text';
            display.placeholder = 'jj/mm/aaaa';
            display.className = input.className || 'form-control form-control-sm';
            display.style.pointerEvents = 'auto';
            display.readOnly = true;
            wrapper.appendChild(display);

            var fp = flatpickr(display, {
                locale: {
                    firstDayOfWeek: 0,
                    weekdays: {
                        shorthand: ['Dim','Lun','Mar','Mer','Jeu','Ven','Sam'],
                        longhand:  ['Dimanche','Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi']
                    },
                    months: {
                        shorthand: ['Jan','Fév','Mar','Avr','Mai','Jun','Jul','Aoû','Sep','Oct','Nov','Déc'],
                        longhand:  ['Janvier','Février','Mars','Avril','Mai','Juin','Juillet','Août','Septembre','Octobre','Novembre','Décembre']
                    }
                },
                dateFormat: 'd/m/Y',
                minDate: 'today',
                disableMobile: true,
                onDayCreate: function(dObj, dStr, fp, dayElem) {
                    var dateStr = toYMD(dayElem.dateObj);
                    if (estDateInterdite(dateStr)) {
                        dayElem.classList.add('flatpickr-disabled');
                        dayElem.title = getTooltip(dateStr);
                    }
                },
                onChange: function(selectedDates, dateStr) {
                    if (selectedDates.length > 0) {
                        var ymd = toYMD(selectedDates[0]);
                        input.value = ymd; // mettre la valeur YYYY-MM-DD dans l'input hidden
                    } else {
                        input.value = '';
                    }
                }
            });
            flatpickrInstances.push(fp);
        }

        function appliquerFlatpickr() {
            document.querySelectorAll('input[name^="date_"]').forEach(function(input) {
                if (!input._flatpickr && input.type !== 'hidden') {
                    initFlatpickr(input);
                }
            });
        }

        // Observer pour les nouvelles lignes
        new MutationObserver(function() {
            if (typeof flatpickr !== 'undefined') {
                appliquerFlatpickr();
            }
        }).observe(document.body, { childList: true, subtree: true });
    })();

//
